struct fio_keyword {
        const char *word;
        const char *desc;
        char *replace;
};

static struct fio_keyword fio_keywords[] = {
        {
                .word   = "$pagesize",
                .desc   = "Page size in the system",
        },
        {
                .word   = "$mb_memory",
                .desc   = "Megabytes of memory online",
        },
        {
                .word   = "$ncpus",
                .desc   = "Number of CPUs online in the system",
        },
        {
                .word   = NULL,
        },
};

void fio_keywords_exit(void)
{
        struct fio_keyword *kw;

        kw = &fio_keywords[0];
        while (kw->word) {
                free(kw->replace);
                kw->replace = NULL;
                kw++;
        }
}

